// Turns lib/fixtures/*.csv into lib/fixtures/index.ts so demo mode works on Vercel
// without reading files at runtime. Run: node scripts/fixtures.mjs
import fs from "fs";
const dir = new URL("../lib/fixtures/", import.meta.url);
const out = {};
for (const f of fs.readdirSync(dir).filter((f) => f.endsWith(".csv")).sort()) {
  out[f.replace(/\.csv$/, "")] = fs.readFileSync(new URL(f, dir), "utf8");
}
fs.writeFileSync(new URL("index.ts", dir),
  "// Generated by scripts/fixtures.mjs from the CSV files in this folder.\n" +
  "// Sample data for DEMO_MODE (snapshot of 19 Nov 2026; employee names replaced).\n" +
  "export const FIXTURES: Record<string, string> = " + JSON.stringify(out, null, 1) + ";\n");
console.log("fixtures:", Object.keys(out).join(", "));
